///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// 아래의 라인부터는 페이지 로딩 위주로 작성합니다.
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

/**
 * 페이지 로딩시 처리
 */
scwin.onpageload = function() {
  scwin.fn.init();
};


///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// 아래의 라인부터는 사용자 정의 상수 위주로 작성합니다.
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
scwin.enumcode = {};//enum 코드

///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// 아래의 라인부터는 사용자 정의 Function 위주로 작성합니다.
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

scwin.fn = {};

/**
 * 페이지 초기화
 */
scwin.fn.init = function(){

};


///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// 아래의 라인부터는 컴포넌트의 사용자 정의  Function 위주로 작성합니다.
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////


/**
 * customFormatter function Objec 생성 
 */
scwin.customFormatter = {};

/**
 * 출발편_출발정보
 */
scwin.customFormatter.grd_depDepInfo = function(data, formattedData, rowIndex, colIndex) {
  let departureDate = dlt_depList.getCellData(rowIndex, "departureDate");
  let departureTime = dlt_depList.getCellData(rowIndex, "departureTime");
  let departureAirportCode = dlt_depList.getCellData(rowIndex, "departureAirportCode");
  let departureAirportName = dlt_depList.getCellData(rowIndex, "departureAirportName");

  formattedData = "{0} {1} {2}({3})".format(departureDate,departureTime,departureAirportCode,departureAirportName);
  return formattedData;
}

/**
 * 출발편_도착정보
 */
scwin.customFormatter.grd_depArrInfo = function(data, formattedData, rowIndex, colIndex) {
  let arrivalDate = dlt_depList.getCellData(rowIndex, "arrivalDate");
  let arrivalTime = dlt_depList.getCellData(rowIndex, "arrivalTime");
  let arrivalAirportCode = dlt_depList.getCellData(rowIndex, "arrivalAirportCode");
  let arrivalAirportName = dlt_depList.getCellData(rowIndex, "arrivalAirportName");

  formattedData = "{0} {1} {2}({3})".format(arrivalDate,arrivalTime,arrivalAirportCode,arrivalAirportName);
  return formattedData;
}

/**
 * 출발편_항공
 */
scwin.customFormatter.grd_depAirline = function(data, formattedData, rowIndex, colIndex) {
  let airlineCode = dlt_depList.getCellData(rowIndex, "airlineCode");
  let flightNumber = dlt_depList.getCellData(rowIndex, "flightNumber");
  let logo = "<img src=\"https://www.verygoodtour.com/images/air_logo/air_{0}01.gif\"/>".format(airlineCode);
  formattedData = "{0} {1} {2}".format(logo, airlineCode, flightNumber);
  return formattedData;
}


/**
 * 출발편_세그 공항정보(1)
 */
scwin.customFormatter.grd_depSegAirportCode1 = function(data, formattedData, rowIndex, colIndex) {

  let seg_departureAirport = dlt_depList.getCellData(rowIndex, "seg_departureAirport1");
  let seg_arrivalAirport = dlt_depList.getCellData(rowIndex, "seg_arrivalAirport1");
  if(seg_departureAirport) formattedData = "{0} - {1}".format(seg_departureAirport, seg_arrivalAirport);

  return formattedData;
}

/**
 * 출발편_세그 공항정보(2)
 */
scwin.customFormatter.grd_depSegAirportCode2 = function(data, formattedData, rowIndex, colIndex) {

  let seg_departureAirport = dlt_depList.getCellData(rowIndex, "seg_departureAirport2");
  let seg_arrivalAirport = dlt_depList.getCellData(rowIndex, "seg_arrivalAirport2");
  if(seg_departureAirport) formattedData = "{0} - {1}".format(seg_departureAirport, seg_arrivalAirport);

  return formattedData;
}

/**
 * 출발편_세그 공항정보(3)
 */
scwin.customFormatter.grd_depSegAirportCode3 = function(data, formattedData, rowIndex, colIndex) {

  let seg_departureAirport = dlt_depList.getCellData(rowIndex, "seg_departureAirport3");
  let seg_arrivalAirport = dlt_depList.getCellData(rowIndex, "seg_arrivalAirport3");
  if(seg_departureAirport) formattedData = "{0} - {1}".format(seg_departureAirport, seg_arrivalAirport);

