}

/**
 * 출발편_세그 항공시간(1)
 */
scwin.customFormatter.grd_depSegDateInfo1 = function(data, formattedData, rowIndex, colIndex) {
  let seg_departureDate = dlt_depList.getCellData(rowIndex, "seg_departureDate1");
  let seg_departureTime = dlt_depList.getCellData(rowIndex, "seg_departureTime1");
  let seg_arrivalDate = dlt_depList.getCellData(rowIndex, "seg_arrivalDate1");
  let seg_arrivalTime = dlt_depList.getCellData(rowIndex, "seg_arrivalTime1");

  if(seg_departureDate) formattedData = "{0} {1} - {2} {3}".format(seg_departureDate, seg_departureTime, seg_arrivalDate, seg_arrivalTime);

  return formattedData;
}

/**
 * 출발편_세그 항공시간(2)
 */
