}

/**
 * 출발편_세그 항공(1)
 */
scwin.customFormatter.grd_depSegAirline1 = function(data, formattedData, rowIndex, colIndex) {
  let seg_marketingCarrier = dlt_depList.getCellData(rowIndex, "seg_marketingCarrier1");
  let seg_flightNumber = dlt_depList.getCellData(rowIndex, "seg_flightNumber1");
  let logo = "<img src=\"https://www.verygoodtour.com/images/air_logo/air_{0}01.gif\"/>".format(seg_marketingCarrier);
  let seg_operationCarrier = dlt_depList.getCellData(rowIndex, "seg_operationCarrier1");
  let logo_operationCarrier = "<img src=\"https://www.verygoodtour.com/images/air_logo/air_{0}01.gif\"/>".format(seg_operationCarrier);

  if(seg_marketingCarrier) {
    formattedData = "{0} {1} {2}".format(logo,seg_marketingCarrier, seg_flightNumber);

    if(seg_operationCarrier) {
      formattedData += "({0} {1})".format(logo_operationCarrier,seg_operationCarrier);
    }
  }

  return formattedData;
}

/**
 * 출발편_세그 항공(2)
 */
