  //데이터가 없는 경우 row 숨김 처리
  //문제 발생 숨김 처리 적용 후 그리그 스크롤이 발생함 스크롤이 발생하면은 안되게 처리 필요
 $.each(dlt_depList.getAllJSON(), function(i,v){
    if(v.byWayCount == 0) {
      grd_depList.setCellVisible(i,12,false);
      grd_depList.setCellVisible(i,13,false);
      grd_depList.setCellVisible(i,14,false);
      grd_depList.setCellVisible(i,15,false);
      grd_depList.setCellVisible(i,16,false);
      grd_depList.setCellVisible(i,17,false);
      grd_depList.setCellVisible(i,18,false);
      grd_depList.setCellVisible(i,19,false);
    } else if(v.byWayCount == 1) {
      grd_depList.setCellVisible(i,16,false);
      grd_depList.setCellVisible(i,17,false);
      grd_depList.setCellVisible(i,18,false);
      grd_depList.setCellVisible(i,19,false);
    }
  });
