scwin.btn_popup_onclick = function(e) {
  let url = "/ui/temp/test_grid_setCellVisible.xml";
  let data = {
              //'callbackFn':'scwin.fn.callbackByPopupTrans',
              //'sendData':dma_popupSearch.getJSON()
             }

  var options = {
              id: "airSeatTransSearchPopup"
              ,popupName: "교통편 검색"
              ,modal : true
              ,width: 1300
              ,height: 640
            };

  com.win.openPopup(url, options, data);
};


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('grd_depList_scrollY_div').style.width == '0px';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('grd_depList_body_tbody').children[0].style.display != 'none';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_data4').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_data3').click()");
		WebSquare.wUnit.addCommand("pause", "400");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
